import{_ as a,o as r,c as n,a5 as t}from"./chunks/framework.DGp912Ge.js";const h=JSON.parse('{"title":"Electrical Safety","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/safety/electrical-safety.md","filePath":"manual/safety/electrical-safety.md","lastUpdated":1785806273000}'),s={name:"manual/safety/electrical-safety.md"};function i(o,e,l,c,d,p){return r(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="electrical-safety" tabindex="-1">Electrical Safety <a class="header-anchor" href="#electrical-safety" aria-label="Permalink to &quot;Electrical Safety&quot;">​</a></h1><p>Safety rules when working with <strong>electrical equipment</strong> such as the RBQ, chargers, and docking stations.</p><ul><li><strong>When it applies</strong>: During charging, inspection, and repair; whenever you handle electrical equipment directly.</li><li><strong>Field use</strong>: In hazardous environments, military use, patrol, etc., ideal electrical conditions may be hard to maintain. Perform charging, internal inspection, and wiring work in a dry, safe place whenever possible.</li></ul><p><strong>High-voltage areas, wet parts, and damaged cables or connectors</strong> pose shock risk. Even if they look intact, <strong>high voltage or strong EMI</strong> can cause latent damage-stop use and inspect if anything seems wrong.</p><h2 id="general-precautions" tabindex="-1">General precautions <a class="header-anchor" href="#general-precautions" aria-label="Permalink to &quot;General precautions&quot;">​</a></h2><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">WARNING</p><p>Post clear warning signs near electrical equipment where shock is possible.</p></div></div><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">WARNING</p><p>1) Do not tear, damage, or remove covers. Be careful when handling labeled parts and nearby components.<br>2) Do not touch internal electrical parts to avoid shock.<br>3) When charging, inspecting, or repairing, do not touch power cables, charging ports, or the controller with wet hands.</p></div></div><h2 id="charging-and-power" tabindex="-1">Charging and power <a class="header-anchor" href="#charging-and-power" aria-label="Permalink to &quot;Charging and power&quot;">​</a></h2><ul><li><strong>Designated charger only</strong>: Charge the RBQ10 only with the supplied RBQ10 dedicated charger or docking station. Other chargers risk damage, fire, or shock.</li><li><strong>Cable check</strong>: Ensure charging and power cables are not tangled or damaged; do not use if damaged.</li><li><strong>Grounding</strong>: Where you charge or inspect, ensure the controller and docking station are properly grounded per regulations. In field or mobile use, charge in as safe a location as possible.</li></ul><h2 id="repair-and-disassembly" tabindex="-1">Repair and disassembly <a class="header-anchor" href="#repair-and-disassembly" aria-label="Permalink to &quot;Repair and disassembly&quot;">​</a></h2><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">WARNING</p><p>For internal inspection, part replacement, or cable work, <strong>turn power off</strong> and disconnect the battery if needed.</p></div></div><ul><li><strong>No unauthorized modifications</strong>: Do not alter electrical circuits or wiring yourself.</li></ul><p>If you have a problem, contact Rainbow Robotics. See <a href="/RBQ/manual/troubleshooting/error-reporting.html">Contact / Error Reporting</a>.</p>',13)])])}const u=a(s,[["render",i]]);export{h as __pageData,u as default};
